@Test func catalogDecodes() throws {
    let msg = try JSONDecoder().decode(Message.self, from: Data(catalogFixture.utf8))
    let cat = try #require(msg.catalog)
    #expect(msg.type == "catalog")
    #expect(!cat.containers.isEmpty)
    #expect(cat.domains.minDimension == 32)
    #expect(cat.domains.resolutions.contains { $0.id == "4k" && $0.width == 3840 })
}

@Test func catalogHelpers() throws {
    let msg = try JSONDecoder().decode(Message.self, from: Data(catalogFixture.utf8))
    let cat = try #require(msg.catalog)
    let mp4 = try #require(cat.containers.first { $0.id == "mp4" })
    #expect(cat.videoContainers.contains(mp4))
    #expect(cat.audioContainers.allSatisfy { $0.kind == "audio" })
    #expect(!cat.audioContainers.isEmpty)
    let ids = cat.codecs(for: mp4).map(\.id)
    #expect(ids.contains("h264") && ids.contains("aac"))
    #expect(!ids.contains("vp8"))
    #expect(cat.isAvailable(codecID: "h264"))
    #expect(!cat.isAvailable(codecID: "no-such-codec"))
}

