    #expect(cat.moreAudioContainers.map(\.id) == ["ac3", "wma", "mka", "caf", "au", "amr", "mp2"])
    #expect(cat.commonVideoContainers.count + cat.moreVideoContainers.count == cat.videoContainers.count)
    #expect(cat.commonAudioContainers.count + cat.moreAudioContainers.count == cat.audioContainers.count)
}

